                button, currentCond, targetParent, evtArgs;
            if ($target.find('input').length > 0 && this.options.mode === "advanced") {
                return;
            }
            if (nav === 'next' || nav === 'prev') {
                parent = $('#' + $target.attr('id').substring(0, $target.attr('id').lastIndexOf('_button'))).find('ul');
            }
            if (nav === 'next') {
                // get the currently selected item
                if (parent.data('selectedItem') === undefined) {
                    $target = parent.find('li:first');
                } else {
                    $target = parent.find('li:nth-child(' + (parent.data('selectedItem') + 1) + ')');
                    if ($target.next().length === 0) {
                        // last, get the first
                        $target = parent.find('li:first');
                    } else {
                        $target = $target.next();
                    }
                }
            }
            if (nav === 'prev') {
                // get the currently selected item
                if (parent.data('selectedItem') === undefined) {
                    $target = parent.find('li:last');
                } else {
                    $target = parent.find('li:nth-child(' + (parent.data('selectedItem') + 1) + ')');
                    if ($target.prev().length === 0) {
                        // last, get the first
                        $target = parent.find('li:last');
                    } else {
                        $target = $target.prev();
                    }
                }
            }
