            $('<div id="' + summaryProgressBarLabelId + '_1"></div>').width(summaryProgressBar.width()).addClass(css.summaryProgressBarSecondaryLabel).appendTo($('#' + this._id('_summpbar_progress')).addClass(css.summaryProgressBarInnerProgress));

