            html = html.replace("$playButtonId$", this._id('_ctrls_play')).replace("$progressBarId$", this._id('_ctrls_s')).replace("$fullScreenId$", this._id('_ctrls_fs_btn')).replace("$volumeControlId$", this._id('_ctrls_vc_btn')).replace("$volumeSliderId$", this._id('_ctrls_vs')).replace("$progressLabelId$", this._id('_ctrls_pl'));

